// Ganti nilai di bawah dengan hasil baca sensor (GPIO, Modbus, MQTT lokal, dsb.)
const baseUrl = flow.get('baseUrl');
const token = flow.get('token');
if (!baseUrl || !token) { node.warn('Atur baseUrl dan token dulu'); return null; }
msg.url = baseUrl + '/api/iot/v1/readings';
msg.headers = { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' };
msg.payload = { temperature: 28.4, humidity: 70, ammonia: 11 };
return msg;

const baseUrl = flow.get('baseUrl');
const token = flow.get('token');
if (!baseUrl || !token) return null;
msg.method = 'GET';
msg.url = baseUrl + '/api/iot/v1/commands';
msg.headers = { 'Authorization': 'Bearer ' + token };
return msg;

// msg.payload = { id, command, payload }. Ganti bagian switch dengan kendali relay/GPIO Anda.
const c = msg.payload;
let result = 'ok';
switch (c.command) {
  case 'feeder_on':  /* nyalakan pakan otomatis */ break;
  case 'feeder_off': break;
  case 'fan_on':     break;
  case 'fan_off':    break;
  default: result = 'perintah tidak dikenal';
}
const baseUrl = flow.get('baseUrl');
const token = flow.get('token');
msg.method = 'POST';
msg.url = baseUrl + '/api/iot/v1/commands/' + c.id + '/ack';
msg.headers = { 'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json' };
msg.payload = { result };
return msg;
